def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    score_me = 0
    score_op = 0
    for my, op in history:
        if my == 'C' and op == 'C':
            score_me += 3
            score_op += 3
        elif my == 'C' and op == 'D':
            score_me += 0
            score_op += 5
        elif my == 'D' and op == 'C':
            score_me += 5
            score_op += 0
        else:
            score_me += 1
            score_op += 1

    if n >= 4:
        op_last4 = [op for _, op in history[-4:]]
        if op_last4.count('D') >= 3:
            return 'D'

    if n >= 2:
        last_my, last_op = history[-1]
        if last_op == 'D':
            if n >= 3:
                prev_my, prev_op = history[-2]
                if prev_op == 'C' and last_my == 'C':
                    return 'D'
            if score_op - score_me > 10 and n < 90:
                return 'D'
        if last_op == 'C' and score_me >= score_op - 2 and n < 95:
            return 'C'

    if n >= 8:
        op_d = sum(1 for _, op in history if op == 'D')
        if op_d * 2 > n:
            return 'D'
        elif op_d * 4 < n:
            return 'C'

    if n >= 6:
        recent_op = [op for _, op in history[-6:]]
        if recent_op.count('D') >= 4:
            return 'D'

    if n == 99:
        if score_op - score_me > 3:
            return 'D'
        return 'C'

    if rng.random() < 0.02:
        return 'D' if rng.random() < 0.5 else 'C'

    if n >= 10:
        if score_me < score_op - 5:
            return 'D'
        if score_me > score_op + 15:
            return 'C'

    return 'C'

